// Injected into an untrusted Node child via `node --import`. Node's fetch/undici ignores the
// HTTP_PROXY env vars the sandbox also sets (which cover Go/Python/curl), so this installs a
// global undici dispatcher to route the child's `fetch` through the allowlisting egress gateway
// too — the child does not opt in and cannot see it.
import { ProxyAgent, setGlobalDispatcher } from "undici";

const gateway = process.env.SANDBOX_EGRESS;
if (gateway) {
  setGlobalDispatcher(new ProxyAgent(gateway));
}
